public class FastDateFormat_format_TriageGen5Test {

    @Test
    public void testFormatWithDefaultTimeZone() {
        // Test case where mTimeZoneForced is false (default behavior of getInstance)
        // In FastDateFormat, getInstance() creates an instance where getTimeZoneOverridesCalendar() is false
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        Assert.assertEquals("2023-10-27", result.toString());
        Assert.assertEquals("2023-10-27", buf.toString());
    }








}

