import org.apache.commons.lang3.Validate;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastDateFormat_format_TriageGen5Test {



    @Test
    public void testFormatWithForcedTimeZone() {
        // Test case where mTimeZoneForced is true
        // We use getInstance(pattern, timeZone) which sets the internal timeZone and forces it
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone tz = TimeZone.getTimeZone("GMT");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, tz);

        // Verify that the instance forces the timezone
        Assert.assertTrue("TimeZone should be forced", fdf.getTimeZoneOverridesCalendar());

        // Create a calendar in a different timezone (EST)
        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("America/New_York"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        // Since mTimeZoneForced is true, the format method should clone the calendar 
        // and set it to GMT. 10:00 AM EST is 14:00 or 15:00 GMT depending on DST.
        // Oct 27 is during DST in NY (EDT = UTC-4). So 10:00 EDT = 14:00 UTC.

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // Expected: 2023-10-27 14:00:00
        Assert.assertEquals("2023-10-27 14:00:00", result.toString());
        Assert.assertEquals("2023-10-27 14:00:00", buf.toString());
    }






}

