public class FastDateFormat_format_TriageGen5Test {







    @Test
    public void testFormatWithDifferentLocale() {
        // Test locale influence on formatting (e.g., month names if using pattern)
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JANUARY, 1);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // January in French is "janvier"
        Assert.assertTrue(result.toString().toLowerCase().contains("janvier"));
    }


